if (!msg.payload.device_id || !msg.payload.timestamp) {
    node.warn('Missing required fields');
    return null;
}

let count = context.get('messageCount') || 0;
count++;
context.set('messageCount', count);

msg.enriched = {
    ...msg.payload,
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: { valid: true, latency_ms: Date.now() - (msg.payload.timestamp * 1000) }
};

node.status({ fill: 'green', shape: 'dot', text: `${msg.payload.device_id} (${count})` });
return msg;

msg.payload = { ...msg.enriched, category: 'PLC', priority: 'high' };
msg.topic = 'collector/ingest';
return msg;

msg.payload = { ...msg.enriched, category: 'Sensor', priority: 'medium' };
msg.topic = 'collector/ingest';
return msg;

// Extract device from topic: factory/command/Conveyor1
let device = msg.topic.split('/').pop();
let payload = msg.payload;

node.warn("📡 MQTT COMMAND | Device: " + device + " | Payload: " + JSON.stringify(payload));

// Update flow context immediately with timestamp
if (device === 'Conveyor1' && payload.is_on !== undefined) {
    flow.set('c1_on', payload.is_on);
    flow.set('Conveyor1_cmd_time', Date.now());
    // Preserve RPM if not provided
    if (payload.rpm === undefined) {
        payload.rpm = flow.get('c1_rpm') || 0;
    }
}
if (device === 'Conveyor2' && payload.is_on !== undefined) {
    flow.set('c2_on', payload.is_on);
    flow.set('Conveyor2_cmd_time', Date.now());
    if (payload.rpm === undefined) {
        payload.rpm = flow.get('c2_rpm') || 0;
    }
}
if (device === 'Placer1') {
    if (payload.is_on !== undefined) {
        flow.set('p1_on', payload.is_on);
        flow.set('Placer1_cmd_time', Date.now());
    }
    if (payload.In_operation !== undefined) {
        flow.set('p1_ready', payload.In_operation);
        flow.set('Placer1_cmd_time', Date.now());
    }
}

// Send to Unreal on factory/data topic
return { topic: "factory/data/" + device, payload: payload };

// Filter: Ensure we only process data if it has a value
if (!msg.payload || typeof msg.payload.value === 'undefined') return null;

let addr = msg.payload.address;
let val = msg.payload.value;
let register = msg.payload.register || 'holding';

node.warn("🔍 COMMAND RECEIVED | Type: " + register + " | Addr: " + addr + " | Val: " + val);

let device = null;
let payload = null;

// --- 1. HANDLE COIL WRITES (Bits 1-4 from Ignition) ---
if (register === 'coils') {
    // Ignition uses 1-based addressing, so Bit1 = coil address 1 (buffer coil 0)
    // Extract boolean from buffer (val is a Buffer object)
    let isOn = false;
    if (Buffer.isBuffer(val)) {
        // Read the specific coil bit from the buffer
        let byteIndex = Math.floor(addr / 8);
        let bitIndex = addr % 8;
        isOn = (val[byteIndex] & (1 << bitIndex)) !== 0;
    } else {
        // Fallback: treat as integer
        isOn = val > 0;
    }

    node.warn("🎛️ COIL WRITE | Addr: " + addr + " | Value: " + isOn);

    // Map coil addresses to devices (with 1-based addressing)
    if (addr === 1) { device = 'Conveyor1'; payload = { is_on: isOn }; }
    else if (addr === 2) { device = 'Conveyor2'; payload = { is_on: isOn }; }
    else if (addr === 3) { device = 'Placer1'; payload = { is_on: isOn }; }
    else if (addr === 4) { device = 'Placer1'; payload = { In_operation: isOn }; }
}

// --- 2. HANDLE HOLDING REGISTER WRITES (Integers) ---
if (register === 'holding') {
    // Boolean switches (Registers 10-13) - for backwards compatibility
    if (addr === 10) { device = 'Conveyor1'; payload = { is_on: val > 0 }; }
    else if (addr === 11) { device = 'Conveyor2'; payload = { is_on: val > 0 }; }
    else if (addr === 12) { device = 'Placer1'; payload = { is_on: val > 0 }; }
    else if (addr === 13) { device = 'Placer1'; payload = { In_operation: val > 0 }; }
    // Integer controls (RPM sliders, etc.)
    else if (addr === 0) { device = 'Conveyor1'; payload = { rpm: val, is_on: true }; }
    else if (addr === 1) { device = 'Conveyor2'; payload = { rpm: val, is_on: true }; }
}

// If we got a valid command, mark the timestamp and update flow context
if (device && payload) {
    flow.set(device + '_cmd_time', Date.now());

    // Update flow context immediately so ticker uses new value
    if (device === 'Conveyor1' && payload.is_on !== undefined) flow.set('c1_on', payload.is_on);
    if (device === 'Conveyor2' && payload.is_on !== undefined) flow.set('c2_on', payload.is_on);
    if (device === 'Placer1' && payload.is_on !== undefined) flow.set('p1_on', payload.is_on);
    if (device === 'Placer1' && payload.In_operation !== undefined) flow.set('p1_ready', payload.In_operation);

    node.warn("✅ SENDING COMMAND | Device: " + device + " | Payload: " + JSON.stringify(payload));
    return { topic: "factory/data/" + device, payload: payload };
}

return null;

// THE BRAIN - DIAGNOSTIC MODE (WITH ADVANCED JSON REPAIR)
// 1. Repairs Broken JSON from Unreal (Commas, Decimals, Separators)
// 2. Routes Real Data
// 3. Syncs Status to Modbus Registers 0-13 for Ignition
// 4. Syncs Booleans to COILS (Bits) 1-4 for Ignition
// 5. Handles HMI Commands (ignores Unreal updates for 2 seconds after command)

// --- 1. HANDLE INCOMING DATA (From Unreal or Sim) ---
if (msg.payload && msg.topic && msg.topic.startsWith('factory/data/') && msg.topic !== 'tick') {
    try {
        // --- JSON REPAIR STATION ---
        let raw = msg.payload.toString();

        // Fix 1: Remove thousand separators inside numbers (e.g. "1,234" -> "1234")
        raw = raw.replace(/(\d+),(\d{3})/g, '$1$2');

        // Fix 2: Insert missing commas after decimal numbers before keys
        // Handles: 7.0 "In_operation" -> 7.0, "In_operation"
        raw = raw.replace(/(\d+\.\d+)\s+"/g, '$1, "');

        // Fix 3: Repair dangling decimals after comma insertion
        // Finds: Digit followed by dot, then space (e.g. 9. "In...)
        // Replaces with: Digit + .0 + space (e.g. 9.0 "In...)
        raw = raw.replace(/(\d+)\.\s/g, '$1.0 ');

        // Fix 4: Insert missing commas between other values and keys
        // Finds: (true OR false OR integers) followed by a space and a quote
        // Replaces with: value + comma + quote
        raw = raw.replace(/((?:true|false|\d+))\s+"/g, '$1, "');

        // Parse the fixed JSON
        let data = JSON.parse(raw);
        let dev = msg.topic.split('/').pop();

        // Check if this device has a recent command (don't overwrite HMI commands)
        let cmdTime = flow.get(dev + '_cmd_time') || 0;
        let now = Date.now();

        // If command was sent less than 2 seconds ago, ignore Unreal updates
        if (now - cmdTime < 2000) {
            node.warn('⏸️ IGNORING ' + dev + ' update (recent HMI command)');
            return [null, null, { topic: 'collector/ingest', payload: { device: dev, data: data, type: 'UNREAL' } }];
        }

        // Save latest state to Flow Context (Memory)
        if (dev === 'Conveyor1') { flow.set('c1_rpm', data.rpm); flow.set('c1_on', data.is_on); }
        if (dev === 'Conveyor2') { flow.set('c2_rpm', data.rpm); flow.set('c2_on', data.is_on); }
        if (dev === 'Placer1') { flow.set('placer_x', data.posX); flow.set('placer_y', data.posY); flow.set('p1_on', data.is_on); flow.set('p1_ready', data.In_operation); }

        return [null, null, { topic: 'collector/ingest', payload: { device: dev, data: data, type: 'UNREAL' } }];
    } catch (e) {
        // Log the exact string that failed so we can adjust regex if needed
        node.error("⚠️ JSON FAIL: " + e.message + " || RAW: " + msg.payload.toString());
        return null;
    }
}

// --- 2. SYNC TO IGNITION (On Tick) ---
if (msg.topic === 'tick') {
    // Retrieve values from memory
    let c1 = flow.get('c1_rpm') || 0;
    let c2 = flow.get('c2_rpm') || 0;
    let px = flow.get('placer_x') || 0;
    let py = flow.get('placer_y') || 0;

    // Booleans
    let c1_on = flow.get('c1_on') || false;
    let c2_on = flow.get('c2_on') || false;
    let p1_on = flow.get('p1_on') || false;
    let p1_ready = flow.get('p1_ready') || false;

    // --- HOLDING REGISTERS (for integer values) ---
    // Create Buffer (28 bytes for registers 0-13)
    let holdingBuf = Buffer.alloc(28);

    // WRITE INTEGERS (Registers 0-3)
    holdingBuf.writeUInt16BE(c1, 0);  // HR0
    holdingBuf.writeUInt16BE(c2, 2);  // HR1
    holdingBuf.writeUInt16BE(px, 4);  // HR2
    holdingBuf.writeUInt16BE(py, 6);  // HR3

    // WRITE BOOLEANS AS INTEGERS (Registers 10-13) - for backwards compatibility
    // HR10 starts at byte 20
    holdingBuf.writeUInt16BE(c1_on ? 1 : 0, 20);
    holdingBuf.writeUInt16BE(c2_on ? 1 : 0, 22);
    holdingBuf.writeUInt16BE(p1_on ? 1 : 0, 24);
    holdingBuf.writeUInt16BE(p1_ready ? 1 : 0, 26);

    // --- COILS (proper bit-packing in single byte) ---
    // Modbus coils are bit-packed: coils 0-7 in byte 0, coils 8-15 in byte 1, etc.
    // With Ignition 1-based addressing: C1=coil0, C2=coil1, C3=coil2, C4=coil3
    let coilBuf = Buffer.alloc(1);
    let byte0 = 0;
    if (c1_on) byte0 |= (1 << 0);     // Bit 0 → Coil 0 → Ignition C1
    if (c2_on) byte0 |= (1 << 1);     // Bit 1 → Coil 1 → Ignition C2
    if (p1_on) byte0 |= (1 << 2);     // Bit 2 → Coil 2 → Ignition C3
    if (p1_ready) byte0 |= (1 << 3);  // Bit 3 → Coil 3 → Ignition C4
    coilBuf[0] = byte0;

    // Send to Modbus Server
    // Output 0: Holding Registers (integers) - start at address 0
    // Output 1: Coils (bits) - start at address 0 (Ignition 1-based adds 1)
    // Output 2: Collector data
    return [
        { payload: { value: holdingBuf, register: 'holding', address: 0, disableMsgOutput: 1 } },
        { payload: { value: coilBuf, register: 'coils', address: 0, disableMsgOutput: 1 } },
        null
    ];
}

return null;

// Format data for collector/ingest topic
// Handles both Unreal Engine devices and Python Simulator sensors

// Handle UNREAL device data from THE BRAIN
if (msg.payload.type === 'UNREAL' && msg.payload.device && msg.payload.data) {
    let timestamp = Date.now() / 1000;
    let device = msg.payload.device;
    let data = msg.payload.data;
    node.warn('FORMAT: ✅ Unreal Device=' + device + ' Data=' + JSON.stringify(data));

    let metadata = {
        tenant: 'accenture',
        factory: 'test_factory',
        processed_at: new Date().toISOString(),
        category: 'UNREAL',
        priority: 'medium'
    };

    // Create device message with proper structure for collector
    let deviceMsg = {
        device_id: device.toLowerCase(),
        type: 'UNREAL',
        timestamp: timestamp,
        data: data,
        metadata: metadata
    };

    node.warn('FORMAT: ➡️ Sending to collector/ingest - ' + JSON.stringify(deviceMsg));
    return { topic: 'collector/ingest', payload: deviceMsg };
}

// Handle Python Simulator sensor data
if (msg.payload && msg.payload.type === 'sensor') {
    node.warn('FORMAT: ✅ Simulator Sensor=' + msg.payload.device_id);
    // Simulator data is already in the correct format, just forward it
    return { topic: 'collector/ingest', payload: msg.payload };
}

// Unknown message type - log warning
node.warn('FORMAT: ⚠️ Unknown message type: ' + JSON.stringify(msg.payload));
return null;

// Extract device name from URL parameter
let device = msg.req.params.device;
let payload = msg.payload;

node.warn("📡 HTTP COMMAND | Device: " + device + " | Payload: " + JSON.stringify(payload));

// Update flow context immediately with timestamp
if (device === 'Conveyor1' && payload.is_on !== undefined) {
    flow.set('c1_on', payload.is_on);
    flow.set('Conveyor1_cmd_time', Date.now());
    // Preserve RPM if not provided
    if (payload.rpm === undefined) {
        payload.rpm = flow.get('c1_rpm') || 0;
    }
}
if (device === 'Conveyor2' && payload.is_on !== undefined) {
    flow.set('c2_on', payload.is_on);
    flow.set('Conveyor2_cmd_time', Date.now());
    if (payload.rpm === undefined) {
        payload.rpm = flow.get('c2_rpm') || 0;
    }
}
if (device === 'Placer1') {
    if (payload.is_on !== undefined) {
        flow.set('p1_on', payload.is_on);
        flow.set('Placer1_cmd_time', Date.now());
    }
    if (payload.In_operation !== undefined) {
        flow.set('p1_ready', payload.In_operation);
        flow.set('Placer1_cmd_time', Date.now());
    }
}

// Return both MQTT message and HTTP response
return [
    { topic: "factory/data/" + device, payload: payload },  // To MQTT
    { payload: { success: true, device: device, command: payload } }  // To HTTP response
];
